CREATE TABLE app_users (id varchar(36) PRIMARY KEY, username varchar(100) NOT NULL UNIQUE, password_hash varchar(100) NOT NULL, created_at timestamp with time zone NOT NULL);
CREATE TABLE sessions (token_hash varchar(64) PRIMARY KEY, user_id varchar(36) NOT NULL REFERENCES app_users(id), expires_at timestamp with time zone NOT NULL);
CREATE TABLE documents (id varchar(36) PRIMARY KEY, owner_id varchar(36) NOT NULL REFERENCES app_users(id), filename varchar(255) NOT NULL, document_type varchar(20) NOT NULL, content_type varchar(100) NOT NULL, file_hash varchar(64) NOT NULL, file_bytes bigint NOT NULL, image_width integer NOT NULL, image_height integer NOT NULL, created_at timestamp with time zone NOT NULL, version bigint NOT NULL, head_revision_id varchar(36), active_job_id varchar(36), upload_key varchar(100), UNIQUE(owner_id, upload_key));
CREATE TABLE jobs (id varchar(36) PRIMARY KEY, document_id varchar(36) NOT NULL REFERENCES documents(id), state varchar(20) NOT NULL, stage varchar(50) NOT NULL, error_code varchar(80), error_message varchar(500), created_at timestamp with time zone NOT NULL, updated_at timestamp with time zone NOT NULL, deadline timestamp with time zone NOT NULL, lease_until timestamp with time zone, lease_token varchar(36), attempts integer NOT NULL, request_key varchar(100), pipeline_manifest varchar(100) NOT NULL, mode varchar(20) NOT NULL, result_run_id varchar(36) NOT NULL, UNIQUE(document_id, request_key));
CREATE TABLE extraction_runs (id varchar(36) PRIMARY KEY, job_id varchar(36) NOT NULL UNIQUE REFERENCES jobs(id), document_id varchar(36) NOT NULL REFERENCES documents(id), result_json text NOT NULL, created_at timestamp with time zone NOT NULL);
CREATE TABLE revisions (id varchar(36) PRIMARY KEY, document_id varchar(36) NOT NULL REFERENCES documents(id), parent_id varchar(36) REFERENCES revisions(id), run_id varchar(36) NOT NULL REFERENCES extraction_runs(id), payload_json text NOT NULL, metadata_json text NOT NULL, issues_json text NOT NULL, row_ids_json text NOT NULL, origin varchar(20) NOT NULL, actor_id varchar(36) NOT NULL REFERENCES app_users(id), reason varchar(1000) NOT NULL, created_at timestamp with time zone NOT NULL, approved_at timestamp with time zone, approved_by varchar(36) REFERENCES app_users(id), approval_reason varchar(1000), acknowledgements_json text);
ALTER TABLE documents ADD CONSTRAINT fk_document_head FOREIGN KEY (head_revision_id) REFERENCES revisions(id);
ALTER TABLE documents ADD CONSTRAINT fk_document_job FOREIGN KEY (active_job_id) REFERENCES jobs(id);
CREATE TABLE export_artifacts (id varchar(36) PRIMARY KEY, document_id varchar(36) NOT NULL REFERENCES documents(id), revision_id varchar(36) NOT NULL REFERENCES revisions(id), exporter_version integer NOT NULL, body_json text NOT NULL, sha256 varchar(64) NOT NULL, created_at timestamp with time zone NOT NULL, UNIQUE(revision_id, exporter_version));
CREATE TABLE audit_events (id varchar(36) PRIMARY KEY, document_id varchar(36) NOT NULL REFERENCES documents(id), actor_id varchar(36), action varchar(50) NOT NULL, details_json text NOT NULL, created_at timestamp with time zone NOT NULL);
CREATE INDEX ix_documents_owner ON documents(owner_id, created_at);
CREATE INDEX ix_jobs_poll ON jobs(state, lease_until, created_at);
CREATE INDEX ix_revisions_document ON revisions(document_id, created_at);
CREATE INDEX ix_audit_document ON audit_events(document_id, created_at);
